package app.smriti.data

import android.content.res.AssetManager
import app.smriti.domain.NormRect
import app.smriti.domain.SceneId
import app.smriti.domain.artKey
import kotlinx.serialization.Serializable
import kotlinx.serialization.json.Json

/** Generated by art_source/generator/build.py next to each scene image. */
@Serializable
data class SceneLayout(
    val scene: String,
    val variant: String,
    val image: String,
    val width: Int,
    val height: Int,
    val safeArea: NormRect,
    val hotspots: List<HotspotLayout>,
)

@Serializable
data class HotspotLayout(val id: String, val rect: NormRect)

enum class LayoutVariant(val key: String) { LANDSCAPE("land"), PORTRAIT("port") }

interface SceneLayoutSource {
    fun layout(scene: SceneId, variant: LayoutVariant): SceneLayout?
}

/** Reads layouts from the APK's assets once and caches them. A missing file yields null, never a crash. */
class AssetSceneLayouts(private val assets: AssetManager) : SceneLayoutSource {
    private val cache = mutableMapOf<Pair<SceneId, LayoutVariant>, SceneLayout?>()

    override fun layout(scene: SceneId, variant: LayoutVariant): SceneLayout? = synchronized(cache) {
        cache.getOrPut(scene to variant) {
            val key = scene.artKey ?: return@getOrPut null
            runCatching {
                assets.open("scenes/${key}_${variant.key}.json").use { parse(it.readBytes().decodeToString()) }
            }.getOrNull()
        }
    }

    companion object {
        private val json = Json { ignoreUnknownKeys = true }
        fun parse(text: String): SceneLayout = json.decodeFromString(SceneLayout.serializer(), text)
    }
}
